// Generic helper for custom fetch mocking scenarios with more control
export interface FetchMockConfig {
  // Default quote data to return for GET /api/quotes/[token]
  quoteData?: any;
  // Default services to return for GET /api/services
  services?: string[];
  // Custom handler for PUT requests to /api/quotes/[token]
  onUpdate?: (url: string, options: any) => Promise<any>;
  // Custom handler for POST requests to /api/quotes/[token]/items
  onAddService?: (url: string, options: any) => Promise<any>;
  // Custom handler for DELETE requests to /api/quotes/[token]
  onDelete?: (url: string, options: any) => Promise<any>;
  // Catch-all handler for other requests
  onOther?: (url: string, options?: any) => Promise<any>;
}

export const setupCustomFetchMock = (config: FetchMockConfig) => {
  const mockFetch = global.fetch as jest.Mock;

  mockFetch.mockImplementation((url: string, options?: any) => {
    // Handle PUT requests (updates)
    if (url.includes('/api/quotes/') && options?.method === 'PUT') {
      if (config.onUpdate) {
        return config.onUpdate(url, options);
      }
      return Promise.resolve({
        ok: true,
        json: async () => ({ ok: true }),
      });
    }

    // Handle POST requests to items endpoint (add service)
    if (url.includes('/api/quotes/') && url.includes('/items') && options?.method === 'POST') {
      if (config.onAddService) {
        return config.onAddService(url, options);
      }
      return Promise.resolve({
        ok: true,
        json: async () => ({
          ok: true,
          created: { id: 'new-item' },
          pricingRuleLinked: true,
        }),
      });
    }

    // Handle DELETE requests
    if (url.includes('/api/quotes/') && options?.method === 'DELETE') {
      if (config.onDelete) {
        return config.onDelete(url, options);
      }
      return Promise.resolve({
        ok: true,
        json: async () => ({ ok: true }),
      });
    }

    // Handle GET requests to quotes endpoint
    if (url.includes('/api/quotes/')) {
      return Promise.resolve({
        ok: true,
        json: async () => config.quoteData || {},
      });
    }

    // Handle GET requests to services endpoint
    if (url.includes('/api/services')) {
      return Promise.resolve({
        ok: true,
        json: async () => ({ services: config.services || [] }),
      });
    }

    // Use custom handler for other requests
    if (config.onOther) {
      return config.onOther(url, options);
    }

    return Promise.reject(new Error(`Unhandled URL: ${url}`));
  });

  return mockFetch;
};

