        resolveServices = resolve;
      });

      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          // Return the delayed promise for services
          return servicesPromise.then(() => Promise.resolve({
            ok: true,
            json: async () => ({ services: mockServices }),
          }));
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      // Should show loading state
      await waitFor(() => {
        expect(screen.getByText('Loading services...')).toBeInTheDocument();
      });

      // Resolve services
      resolveServices!({ services: mockServices });

      // Should show services
      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });
    });

    it('should show error state when services fail to load', async () => {
      // Reset mockFetch for this test and set up URL-based mocking
      mockFetch.mockReset();
      mockFetch.mockImplementation((url: string) => {
        if (url.includes('/api/quotes/')) {
          return Promise.resolve({
            ok: true,
            json: async () => mockQuoteData,
          });
        } else if (url.includes('/api/services')) {
          // Return error for services fetch
          return Promise.resolve({
            ok: false,
            status: 500,
          });
        }
        return Promise.reject(new Error(`Unhandled URL: ${url}`));
      });

      render(<QuoteViewerPage />);

      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Open modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      // Should show error state
      await waitFor(() => {
        expect(screen.getByText('Failed to fetch services: 500')).toBeInTheDocument();
      });
    });
  });
});

