'use client';

import { useState, useEffect, useMemo, useCallback } from 'react';

interface ServicesResponse {
  services: string[];
  error?: string;
}

interface UseServicesResult {
  services: string[];
  isLoading: boolean;
  error: string | null;
  refetch: () => void;
}

export function useServices(existingServices: string[] = []): UseServicesResult {
  const [services, setServices] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Stabilize existingServices array to prevent unnecessary re-renders
  const stableExistingServices = useMemo(() => existingServices, [JSON.stringify(existingServices)]);

  const fetchServices = useCallback(async () => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/services', {
        cache: 'no-store'
      });

      if (!response.ok) {
        throw new Error(`Failed to fetch services: ${response.status}`);
      }

      const data: ServicesResponse = await response.json();

      if (data.error) {
        throw new Error(data.error);
      }

      // Filter out services that are already in the quote
      const allServices = data.services || [];
      const availableServices = allServices.filter(service => 
        !stableExistingServices.includes(service)
      );
      setServices(availableServices);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load services';
      setError(errorMessage);
      setServices([]);
    } finally {
      setIsLoading(false);
    }
  }, [stableExistingServices]);

  useEffect(() => {
    fetchServices();
  }, [fetchServices]);

  const refetch = () => {
    fetchServices();
  };

  return {
    services,
    isLoading,
    error,
    refetch
  };
}

