import QuoteViewerPage from '../page';
import { useParams, useSearchParams } from 'next/navigation';
import { setupFetchMocks, setupStatefulFetchMocks } from '../test-helpers';

// Mock Next.js navigation
jest.mock('next/navigation', () => ({
  useParams: jest.fn(),
  useSearchParams: jest.fn(),
}));

// Mock the Toaster component
jest.mock('@/components/ui/use-toast', () => ({
  useToast: () => ({
    toast: jest.fn(),
  }),
}));

// Mock CTABanner component
jest.mock('@/components/ui/cta-banner', () => ({
  CTABanner: ({ message }: { message: string }) => (
    <div data-testid="cta-banner">{message}</div>
  ),
}));

// Mock Lucide React icons
jest.mock('lucide-react', () => ({
  DollarSign: () => <div data-testid="dollar-icon">$</div>,
  Trophy: () => <div data-testid="trophy-icon">🏆</div>,
  Lock: () => <div data-testid="lock-icon">🔒</div>,
  Plus: () => <div data-testid="plus-icon">+</div>,
  User: () => <div data-testid="user-icon">👤</div>,
  Mail: () => <div data-testid="mail-icon">📧</div>,
  MapPin: () => <div data-testid="map-icon">📍</div>,
  Building: () => <div data-testid="building-icon">🏢</div>,
  Home: () => <div data-testid="home-icon">🏠</div>,
  TreePine: () => <div data-testid="tree-icon">🌲</div>,
  Loader2: ({ className }: { className?: string }) => (
    <div data-testid="loader" className={className}>Loading...</div>
  ),
  X: () => <div data-testid="close-icon">X</div>,
}));

// Mock fetch globally
const mockFetch = jest.fn();
global.fetch = mockFetch;

describe('Duplicate Service Prevention', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockFetch.mockReset();

    // Mock navigation hooks
    (useParams as jest.Mock).mockReturnValue({ token: 'test-token' });
    (useSearchParams as jest.Mock).mockReturnValue({
      get: jest.fn().mockReturnValue(null),
    });
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe('Service Filtering Based on Existing Services', () => {
    it('should not show services that are already in the quote', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning', 'Pressure Washing', 'Handyman'];
      const existingServices = ['Window Washing', 'Handyman'];
      const availableServices = ['Gutter Cleaning', 'Pressure Washing'];

      // Mock quote data with existing services
      const mockQuoteData = {
        quote: {
          id: 'rec123',
          quoteId: 'Q-001',
          token: 'test-token',
          firstName: 'John',
          lastName: 'Doe',
          email: 'john@example.com',
          city: 'Test City',
          alaCarteTotal: 200,
          handldTotal: 140,
        },
        lineItems: [
          {
            id: 'rec456',
            service: 'Window Washing',
            handldRate: 70,
            alaCarteRate: 100,
            chosenFrequency: 1,
            quoteId: 'Q-001',
          },
          {
            id: 'rec789',
            service: 'Handyman',
            handldRate: 80,
            alaCarteRate: 120,
            chosenFrequency: 2,
            quoteId: 'Q-001',
          },
        ],
      };

      setupFetchMocks(mockQuoteData, allServices);

      render(<QuoteViewerPage />);

      // Wait for page to load
      await waitFor(() => {
        expect(screen.getByText('Services')).toBeInTheDocument();
      });

      // Verify existing services are displayed
      expect(screen.getByText('Window Washing')).toBeInTheDocument();
      expect(screen.getByText('Handyman')).toBeInTheDocument();

      // Open the service selection modal
      const addServiceButton = screen.getByText('Add Service');
      fireEvent.click(addServiceButton);

      await waitFor(() => {
        expect(screen.getByText('Select a service to add to your quote:')).toBeInTheDocument();
      });

      // Should only show available services (not existing ones)
      expect(screen.getByText('Gutter Cleaning')).toBeInTheDocument();
      expect(screen.getByText('Pressure Washing')).toBeInTheDocument();

      // Should NOT show existing services in the modal - check specifically within the modal
      const modalContainer = document.querySelector('.fixed.inset-0.z-50');
      if (modalContainer) {
        const modalServiceButtons = modalContainer.querySelectorAll('button span.font-medium.text-brand-navy');
        const modalServices = Array.from(modalServiceButtons).map(btn => btn.textContent);

        expect(modalServices).not.toContain('Window Washing');
        expect(modalServices).not.toContain('Handyman');
        expect(modalServices).toContain('Gutter Cleaning');
        expect(modalServices).toContain('Pressure Washing');
      } else {
        throw new Error('Modal container not found');
      }
    });

    it('should show "No services available" when all services are already added', async () => {
      const allServices = ['Window Washing', 'Gutter Cleaning'];

      // Mock quote data with all available services
      const mockQuoteData = {
        quote: {
